return items.map(item => {
    const j = item.json;

    // --- Extract subject and sender ---
    const subject = j.Subject || j.subject || '';
    const from = j.From || j.from || j.sender || '';

    // --- Extract body safely ---
    let body = '';

    if (j.payload && j.payload.parts) {
        const textPart = j.payload.parts.find(p => p.mimeType === 'text/plain');
        if (textPart && textPart.body && textPart.body.data) {
            body = Buffer.from(textPart.body.data, 'base64').toString('utf-8');
        }
    } else if (j.payload && j.payload.body && j.payload.body.data) {
        body = Buffer.from(j.payload.body.data, 'base64').toString('utf-8');
    } else if (j.snippet) {
        body = j.snippet;
    }

    // --- Remove signatures / disclaimers ---
    body = body.replace(/--\s*[\s\S]*$/gm, '');
    body = body.replace(/Regards,.*$/gm, '');
    body = body.replace(/Best regards,.*$/gm, '');
    body = body.replace(/Sent from my .*$/gm, '');

    // --- Preserve bullet points ---
    body = body.replace(/(\r\n|\r|\n)[*-]\s+/g, '\n• ');

    // --- Extract priority phrases ---
    const urgentPhrases = ['urgent', 'asap', 'action required', 'immediate', 'deadline'];
    let priorityNotes = [];
    urgentPhrases.forEach(p => {
        if (new RegExp(`\\b${p}\\b`, 'gi').test(body)) priorityNotes.push(p);
    });
    priorityNotes = priorityNotes.length ? `High-priority phrases detected: ${priorityNotes.join(', ')}` : 'None';

    // --- Attachments / links ---
    const attachmentsArr = (j.attachments || []).map(a => a.fileName || '').filter(Boolean);
    const attachments = attachmentsArr.length ? attachmentsArr.join(', ') : 'None';
    const links = (body.match(/https?:\/\/[^\s)]+/g) || []).join(', ') || 'None';

    // --- Detect if email contains images ---
    const hasImage = attachmentsArr.some(name => /\.(jpg|jpeg|png|gif)$/i.test(name)) ? 'Yes' : 'No';

    // --- Optional: include PDF/DOC text ---
    // Here we just note that a PDF/DOC exists; actual extraction requires extra nodes
    const docAttachments = attachmentsArr.filter(name => /\.(pdf|doc|docx)$/i.test(name));
    const docTextNote = docAttachments.length 
        ? `Attachment(s) include document(s): ${docAttachments.join(', ')} (text extraction possible)` 
        : 'No documents attached';

    // --- Build content for AI ---
    j.contentForAI = `
Subject: ${subject}
From: ${from}

${body}

${priorityNotes}
Contains Image: ${hasImage}
${docTextNote}

Attachments: ${attachments}
Links: ${links}
`;

    // --- Store separately ---
    j.attachmentNames = attachments;
    j.extractedLinks = links;
    j.priorityNotes = priorityNotes;
    j.hasImage = hasImage;
    j.docAttachments = docAttachments;

    return item;
});

// Each incoming item is an email, all handled in one go
return items.map(item => {
    // Get Gemini's text field for this email
    const rawText = item.json.candidates[0].content.parts[0].text;

    // Remove ```json ... ``` backticks if present
    const cleanedText = rawText.replace(/```json\s*|```/g, '').trim();

    // Safely parse JSON
    let parsed = {};
    try {
        parsed = JSON.parse(cleanedText);
    } catch (err) {
        parsed = { error: 'JSON parse failed', raw: cleanedText };
    }

    // Return new item with parsed summary/action/etc.
    return { json: parsed };
});
